def transform(grid):
    from collections import Counter
    h = len(grid)
    w = len(grid[0]) if h > 0 else 0

    # Find color with a 2x2 block
    block_color = None
    for r in range(h - 1):
        for c in range(w - 1):
            color = grid[r][c]
            if grid[r+1][c] == color and grid[r][c+1] == color and grid[r+1][c+1] == color:
                block_color = color
                break
